        \\█▀▀▀▀▀█ ▄█▄█▀█▄█▀▀  ▀|
        \\█ ███ █  ▀█▀▀▀▀▀▀   ▀|
        \\█ ▀▀▀ █ █▄  ▄ ▀ ▄ ▀▀▀|
        \\▀▀▀▀▀▀▀ ▀ ▀   ▀  ▀▀ ▀|
        \\
    );
    const braille = try grid.asBrailleString(allocator);
    defer allocator.free(braille);
    try expect(braille).toEqualString(
        \\⡏⣭⡍⡇⢻⢽⡃⡏⣭⡍⡇|
        \\⠧⠭⠥⠇⣇⣆⠅⠧⠭⠥⠇|
        \\⠉⠷⡊⠥⢝⠉⡉⠍⣑⠌⡇|
