    const blocks = try grid.asBlockString2(allocator);
    defer allocator.free(blocks);
    try expect(blocks).toEqualString(
        \\█▀▀▀▀▀█ ▄ █ ▀███▄ █▀▀▀▀▀█|
        \\█ ███ █ ▄▄▄ █▀▄█  █ ███ █|
